UPDATE dictation_progress SET direction = :direction, level = :level, source = :source, current_word_id = CAST(:current_word_id AS INTEGER), answered = 0, hinted = 0, asked_ids = :asked_ids, asked_count = 1, right_count = 0, round_start = CAST(:round_start AS INTEGER) WHERE learner = :learner AND subject_id = CAST(:subject_id AS INTEGER)
